SELECT marts.agents.hourly_cost_usd 
FROM marts.agents 
WHERE marts.agents.display_name = 'Farhana Khan' AND marts.agents.team = 'sales';

SELECT marts.dim_tenant.monthly_budget_usd 
FROM marts.dim_tenant
WHERE marts.dim_tenant.tenant_id = 'billing_tenant_id';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE cache_status = 'HIT';

SELECT COUNT(DISTINCT gold_category) 
FROM marts.fct_outcomes 
WHERE split = 'test';

SELECT COUNT(*) 
FROM marts.fct_requests 
WHERE http_status != 200;

SELECT count(*) 
FROM support.agents 
WHERE hourly_cost_usd > 6;

SELECT COUNT(*) 
FROM support.ticket_events 
WHERE event_type = 'reopened';

SELECT AVG(hourly_cost_usd) AS average_hourly_cost_usd 
FROM marts.agents 
WHERE is_active = true;
